package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId string // PIC X(5) @0 len=5
	OrStat string // PIC X(1) @5 len=1
	OrQty int64 // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 // PIC 99 len=2 = 0
var WsShipCount int64 // PIC 99 len=2 = 0
var WsCancelCount int64 // PIC 99 len=2 = 0
var WsInvalid int64 // PIC 99 len=2 = 0
var WsBadQty int64 // PIC 99 len=2 = 0
var WsQtyEd string // PIC ZZ9 len=3
var WsPriceEd string // PIC Z,ZZ9.99 len=8
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var curRec OrderRec
var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatPic(val decimal.Decimal, pic string) string {
	// split pic at '.'
	dotPic := strings.Index(pic, ".")
	var intPic, fracPic string
	hasDot := dotPic >= 0
	if hasDot {
		intPic = pic[:dotPic]
		fracPic = pic[dotPic+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}
	// scale value
	scaled := val.Shift(int32(fracSlots)).Truncate(0).IntPart()
	neg := scaled < 0
	if neg {
		scaled = -scaled
	}
	var intPart, fracPart int64
	if fracSlots > 0 {
		p := pow10(fracSlots)
		intPart = scaled / p
		fracPart = scaled % p
	} else {
		intPart = scaled
		fracPart = 0
	}
	_ = neg // values are non-negative in this program
	intStr := fmt.Sprintf("%d", intPart)
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// pad left with zeros
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}
	firstNZ := -1
	for i := 0; i < len(intStr); i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	var sb strings.Builder
	slotIdx := 0
	for _, c := range intPic {
		switch c {
		case 'Z', '9':
			d := intStr[slotIdx]
			if c == '9' {
				sb.WriteByte(d)
			} else {
				if firstNZ == -1 || slotIdx < firstNZ {
					sb.WriteByte(' ')
				} else {
					sb.WriteByte(d)
				}
			}
			slotIdx++
		case ',':
			if firstNZ == -1 || slotIdx <= firstNZ {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		default:
			sb.WriteByte(byte(c))
		}
	}
	if hasDot {
		sb.WriteByte('.')
		fracStr := fmt.Sprintf("%d", fracPart)
		if len(fracStr) < fracSlots {
			fracStr = strings.Repeat("0", fracSlots-len(fracStr)) + fracStr
		}
		if len(fracStr) > fracSlots {
			fracStr = fracStr[len(fracStr)-fracSlots:]
		}
		fi := 0
		for _, c := range fracPic {
			if c == 'Z' || c == '9' {
				sb.WriteByte(fracStr[fi])
				fi++
			} else {
				sb.WriteByte(byte(c))
			}
		}
	}
	return sb.String()
}

func formatZZ9(v decimal.Decimal) string {
	return formatPic(v, "ZZ9")
}
func formatPrice(v decimal.Decimal) string {
	return formatPic(v, "Z,ZZ9.99")
}
func formatTotal(v decimal.Decimal) string {
	return formatPic(v, "ZZ,ZZZ,ZZ9.99")
}
func formatGrand(v decimal.Decimal) string {
	return formatPic(v, "Z,ZZZ,ZZZ,ZZ9.99")
}

func formatPIC99(v int64) string {
	// keep low-order 2 digits, zero-padded
	m := v % 100
	if m < 0 {
		m = -m
		// sign not expected
	}
	return fmt.Sprintf("%02d", m)
}

func parseQty(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func parsePrice(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	var v int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return decimal.New(v, -2)
}

func makeRecord(line string) OrderRec {
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	return OrderRec{
		OrId:    line[0:5],
		OrStat:  line[5:6],
		OrQty:   parseQty(line[6:9]),
		OrPrice: parsePrice(line[9:15]),
	}
}

func READPARA() {
	if !inputOpen || inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	curRec = makeRecord(inputLines[inputIdx])
	inputIdx++
}

func SHOWPARA() {
	WsQtyEd = formatZZ9(decimal.NewFromInt(curRec.OrQty))
	WsPriceEd = formatPrice(curRec.OrPrice)
	WsTotalEd = formatTotal(WsTotal)
	fmt.Println(curRec.OrId+" "+curRec.OrStat+" "+WsQtyEd+" "+WsPriceEd+" "+WsTotalEd)
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if curRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Println(curRec.OrId + " BAD QTY")
	} else if curRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE (truncated to 2)
		p := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice)
		WsTotal = p.Truncate(2)
		// store truncation to 9(8)V99: keep low order - fits
		WsNewCount = (WsNewCount + 1) % 100
		SHOWPARA()
	} else if curRec.OrStat == "S" {
		p := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice).Mul(decimal.New(105, -2))
		WsTotal = p.Round(2)
		WsShipCount = (WsShipCount + 1) % 100
		SHOWPARA()
	} else if curRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOWPARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Println(curRec.OrId + " BAD STATUS " + curRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	READPARA()
}

func SUMMARYPARA() {
	WsGrandEd = formatGrand(WsGrand)
	fmt.Println("NEW: " + formatPIC99(WsNewCount) + " SHIPPED: " + formatPIC99(WsShipCount) + " CANCELLED: " + formatPIC99(WsCancelCount))
	fmt.Println("INVALID: " + formatPIC99(WsInvalid) + " BAD QTY: " + formatPIC99(WsBadQty))
	fmt.Println("GRAND TOTAL: " + WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.NewFromInt(0)
	WsGrand = decimal.NewFromInt(0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0

	// OPEN INPUT ORDER-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			inputLines = append(inputLines, sc.Text())
		}
		f.Close()
		if sc.Err() != nil {
			fmt.Fprintln(os.Stderr, sc.Err())
			os.Exit(1)
		}
	}
	inputIdx = 0
	inputOpen = true
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	inputOpen = false
	SUMMARYPARA()
}
